sudo firewall-cmd --permanent --add-service={http,https}
sudo firewall-cmd --reload
sudo firewall-cmd --list-services

sudo tee /usr/local/sbin/fw-lab.sh > /dev/null <<'EOF'
#!/bin/bash
set -euo pipefail
fc() { firewall-cmd "$@"; }
fc --permanent --zone=internal --add-source=192.168.56.0/24
fc --permanent --zone=internal --add-service={ssh,cockpit,sklep}
fc --permanent --zone=public --add-service={http,https}
fc --permanent --zone=public --remove-service={ssh,cockpit} || true
fc --reload
diff <(fc --list-all-zones) <(fc --permanent --list-all-zones) > /dev/null && echo 'runtime = permanent'
fc --get-active-zones
EOF
sudo chmod 700 /usr/local/sbin/fw-lab.sh
